public static void add(Node t, Node l, Node r){
    t.maxCnt = 0;
    t.secCnt = 0;

    if (l.max == r.max){
        t.max = l.max;
        t.maxCnt = l.maxCnt + r.maxCnt;
    } else if (l.max > r.max) {
        t.max = l.max;
        t.maxCnt = l.maxCnt;
    } else {
        t.max = r.max;
        t.maxCnt = r.maxCnt;
    }

    t.sec = Integer.MIN_VALUE;
    if (l.max < t.max) {
        t.sec = l.max;
    }
    if (r.max < t.max && r.max > t.sec) {
        t.sec = r.max;
    }
    if (l.sec > t.sec && l.sec < t.max) {
        t.sec = l.sec;
    }
    if (r.sec > t.sec && r.sec < t.max) {
        t.sec = r.sec;
    }

    if (t.sec == l.max) {
        t.secCnt += l.maxCnt;
    }
    if (t.sec == r.max) {
        t.secCnt += r.maxCnt;
    }
    if (t.sec == l.sec) {
        t.secCnt += l.secCnt;
    }
    if (t.sec == r.sec) {
        t.secCnt += r.secCnt;
    }
}
